describe('Table Column Freezing - First Column', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should freeze the first column when scrolling horizontally', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify first column header is visible
    cy.get('[data-testid="table-header-first-column"]').should('be.visible');

    // Verify first column data cells are visible
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('be.visible');
    cy.get('[data-testid="table-cell-first-column-row-2"]').should('be.visible');

    // Scroll horizontally to trigger column freeze
    cy.get('[data-testid="data-table"]').then(($table) => {
      const tableWidth = $table.width();
      const scrollAmount = tableWidth * 1.5;
      cy.wrap($table).scrollTo(0, 0);
      cy.wrap($table).scrollTo(0, 0);
      cy.wrap($table).scrollTo(0, scrollAmount);
    });

    // Verify first column is frozen and remains visible
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('be.visible');
    cy.get('[data-testid="table-cell-first-column-row-2"]').should('be.visible');

    // Verify other columns scroll normally
    cy.get('[data-testid="table-cell-second-column-row-1"]').should('be.visible');
    cy.get('[data-testid="table-cell-third-column-row-1"]').should('be.visible');

    // Verify first column content is not affected by scroll
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('contain', 'ID');
    cy.get('[data-testid="table-cell-first-column-row-2"]').should('contain', '2');
  });

  it('should unfreeze the first column when scroll position is reset', () => {
    // Scroll horizontally to freeze the first column
    cy.get('[data-testid="data-table"]').then(($table) => {
      const tableWidth = $table.width();
      cy.wrap($table).scrollTo(0, tableWidth * 2);
    });

    // Verify first column is frozen
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('be.visible');

    // Reset scroll position
    cy.get('[data-testid="data-table"]').then(($table) => {
      cy.wrap($table).scrollTo(0, 0);
    });

    // Verify first column is no longer frozen and scrolls with the table
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('be.visible');
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('not.have.css', 'position', 'sticky');

    // Verify all columns scroll together
    cy.get('[data-testid="table-cell-second-column-row-1"]').should('be.visible');
    cy.get('[data-testid="table-cell-third-column-row-1"]').should('be.visible');

    // Verify first column content is still visible
    cy.get('[data-testid="table-cell-first-column-row-1"]').should('contain', 'ID');
  });
});
